/**
 * @brief Insert a text to a label. The label text cannot be static.
 *
 * @param pos (number) character index to insert. Expressed in character index and not byte index. 0: before first char. LV_LABEL_POS_LAST: after last char.
 *
 * @param txt (string) pointer to the text to insert
 */
jerry_value_t sni_api_lv_label_ins_text(const jerry_call_info_t *call_info_p,
                                        const jerry_value_t args_p[],
                                        const jerry_length_t args_count)
{
    if (args_count != 2)
    {
        return sni_api_throw_error("Invalid argument count");
    }

    if (!jerry_value_is_object(call_info_p->this_value))
    {
        return sni_api_throw_error("Invalid argument type");
    }
    lv_obj_t *self_obj;
    if (!sni_tb_js2c(call_info_p->this_value, SNI_H_LV_OBJ, &self_obj))
    {
        return sni_api_throw_error("Failed to convert argument");
    }

    if (!jerry_value_is_number(args_p[0]))
    {
        return sni_api_throw_error("Invalid argument type");
    }
    uint32_t arg_pos;
    arg_pos = sni_tb_js2c_uint32(args_p[0]);

    if (!jerry_value_is_string(args_p[1]))
    {
        return sni_api_throw_error("Invalid argument type");
    }
    const char *arg_txt;
    arg_txt = sni_tb_js2c_string(args_p[1]);
    if (!arg_txt)
    {
        return sni_api_throw_error("Out of memory");
    }

    lv_label_ins_text(self_obj, arg_pos, arg_txt);
    eos_free((void *)arg_txt);
    return jerry_undefined();
}

